// Generates src/generated/assets.ts: the stylesheet and the SQL migrations as string constants, so the
// deployed bundle (e.g. on Vercel) never reads files at runtime. tests/assets.test.ts fails when the
// generated file is out of date: run `npm run gen:assets` after changing db/migrations or app.css.
import { readdirSync, readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { PRESENTERS, agentNames, captionsVtt } from "../src/landing/presenters.ts";

export function buildAssets(root = fileURLToPath(new URL("..", import.meta.url))): string {
  const dir = `${root}/db/migrations`;
  const files = readdirSync(dir).filter((f) => /^\d{4}_[a-z0-9_]+\.sql$/.test(f)).sort();
  const migrations = files.map((name) => ({ name, sql: readFileSync(`${dir}/${name}`, "utf8") }));
  const css = readFileSync(`${root}/src/shared/app.css`, "utf8");
  const landingCss = readFileSync(`${root}/src/landing/landing.css`, "utf8");
  const font = readFileSync(`${root}/src/shared/fonts/manrope-latin.woff2`).toString("base64");
  return [
    "// GENERATED by scripts/gen-assets.ts from db/migrations, src/shared/app.css, src/landing/landing.css and the Manrope font. Do not edit by hand.",
    `export const CSS: string = ${JSON.stringify(css)};`,
    `export const LANDING_CSS: string = ${JSON.stringify(landingCss)};`,
    "// Manrope (SIL Open Font License 1.1, src/shared/fonts/MANROPE-OFL.txt), latin subset, variable weight.",
    `export const MANROPE_WOFF2_BASE64: string = ${JSON.stringify(font)};`,
    `export const MIGRATIONS: readonly { name: string; sql: string }[] = ${JSON.stringify(migrations, null, 1)};`,
    "",
  ].join("\n");
}

/** docs/PRESENTER_SCRIPTS.md, generated from src/landing/presenters.ts (the page shows the same lines as captions). */
export function buildPresenterDoc(): string {
  const words = (lines: string[]) => lines.join(" ").split(/\s+/).length;
  const out = [
    "# Presenter video scripts",
    "",
    "_Generated by `npm run gen:assets` from `src/landing/presenters.ts`. Edit the scripts there, not here._",
    "",
    "Seven short videos for the landing page. Each is about 25–35 seconds. The page already plays these lines as captions on an illustrated presenter card until a video exists.",
    "",
    "## Recording",
    "",
    "- **Presenter:** an AI avatar (HeyGen, Synthesia or similar) or a real person from the business. If an AI avatar is used, keep the on-screen label \"AI presenter\". Never use a real person's likeness without their written permission.",
    "- **Format:** 1920×1080 MP4 (H.264, AAC), under 10 MB each if possible. Add a poster frame as a 1280×720 JPG.",
    "- **Speech:** read each script exactly as written. The page's captions (`/captions/<id>.vtt`) are generated from these lines; if you change the words, change them in `src/landing/presenters.ts` too.",
    "- **Claims:** add no numbers, customer names, results or promises that are not in the script. Messages, posts and payments are not sent during the pilot.",
    "- **Publishing:** upload `<id>.mp4` and `<id>.jpg` to one public folder (for example Vercel Blob or the CONARO media host), set `BAI_PRESENTER_VIDEO_BASE` to that folder's address, and redeploy. Every presenter switches from the illustrated card to the video at once.",
    "",
  ];
  for (const p of PRESENTERS) {
    out.push(`## ${p.title} — \`${p.id}\``, "", `- **Name tag:** ${p.presenter}`, `- **Files:** \`${p.id}.mp4\`, \`${p.id}.jpg\``, `- **Length:** about ${Math.round(words(p.script) / 2.6)} seconds (${words(p.script)} words)`);
    const names = agentNames(p);
    if (names.length) out.push(`- **Agents covered:** ${names.join(", ")}`);
    out.push("", "Script:", "", ...p.script.map((l) => `> ${l}`), "", "<details><summary>Caption timings (WebVTT)</summary>", "", "```", captionsVtt(p).trim(), "```", "", "</details>", "");
  }
  return out.join("\n");
}

if (process.argv[1]?.endsWith("gen-assets.ts")) {
  const root = fileURLToPath(new URL("..", import.meta.url));
  mkdirSync(`${root}/src/generated`, { recursive: true });
  writeFileSync(`${root}/src/generated/assets.ts`, buildAssets(root));
  writeFileSync(`${root}/docs/PRESENTER_SCRIPTS.md`, buildPresenterDoc());
  console.log("wrote src/generated/assets.ts");
}
